def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(a.get('occupancy', 1.0) or 0.0)) for a in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', ()):
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and math.isfinite(d) and d > 1e-8:
            if d < nearest[i]:
                nearest[i] = d
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    return float(sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight)

