def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(a.get('occupancy', 1.0) or 0.0)) for a in sites]
    atom_weight = sum(occ)
    if atom_weight <= 0:
        return 0.0
    amounts = {}
    for i in range(n):
        e = sites[i].get('element')
        amounts[e] = amounts.get(e, 0.0) + occ[i]
    random_unlike = 1.0 - sum((x / atom_weight) ** 2 for x in amounts.values())
    nearest = [math.inf] * n
    edges = s.get('neighbors', ())
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and math.isfinite(d) and d > 1e-8:
            if d < nearest[i]:
                nearest[i] = d
    unlike = 0.0
    weight = 0.0
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and math.isfinite(d) and 1e-8 < d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    return float(unlike / weight - random_unlike) if weight > 0 else 0.0

