    mean = sum(w * c for w, c in zip(occ, coord)) / weight
    return float(math.sqrt(max(0.0, sum(w * (c - mean) ** 2 for w, c in zip(occ, coord)) / weight)))"},{"description":"Mean relative bond-length variance within each site's first shell, defined by 1.3 times its nearest distance.","name":"first_shell_bond_distortion","source":"def feature(s):
