                total += occ[i] * occ[j] * (en[i] - en[j]) ** 2 / d
    weight = sum(occ)
    return float(total / (2.0 * weight)) if weight > 0 else 0.0"},{"description":"Excess unlike-element first-shell contact fraction relative to random mixing at the supplied composition.","name":"first_shell_heterochemical_excess","source":"def feature(s):
