    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    radii = [1.0] * n
    for i, site in enumerate(sites):
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            radii[i] = r
    near = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            near[i] = min(near[i], d / (radii[i] + radii[j]))
    total = sum(occ[i] for i in range(n) if near[i] < inf)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * near[i] for i in range(n) if near[i] < inf) / total
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (near[i] - mean) ** 2 for i in range(n) if near[i] < inf) / total
