            nearest[i] = min(nearest[i], d)
    total = 0.0
    square = 0.0
    weight = 0.0
    for i in range(n):
        o = sites[i].get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if isfinite(nearest[i]):
            total += o * nearest[i]
            square += o * nearest[i] * nearest[i]
            weight += o
    if weight <= 0 or total <= 0:
        return 0.0
    mean = total / weight
    return sqrt(max(0.0, square / weight - mean * mean)) / mean"},{"description":"Mean occupied coordination within 1.25 times each site's nearest-neighbor distance.","name":"adaptive_coordination_mean","source":"def feature(s):
