    if weight <= 0:
        return 0.0
    return sqrt(max(0.0, square / weight - (total / weight) ** 2))"},{"description":"Lower-decile shortest contact distance normalized by the endpoint covalent-radius sum.","name":"normalized_contact_lower_decile","source":"def feature(s):
