        if 0 <= i < n and 0 <= j < n and radii[i] > 0 and radii[j] > 0 and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d / (radii[i] + radii[j]))
    values = sorted([x for x in nearest if isfinite(x)])
    if not values:
        return 0.0
    position = 0.1 * (len(values) - 1)
    lo = int(position)
    hi = min(lo + 1, len(values) - 1)
    return values[lo] + (position - lo) * (values[hi] - values[lo])"},{"description":"Mean signed relative bond-length deviation from covalent-radius sums for short contacts.","name":"short_contact_mean_strain","source":"def feature(s):
