        if 0 <= i < n and 0 <= j < n and radii[i] > 0 and radii[j] > 0 and en[i] is not None and en[j] is not None and d is not None and isfinite(d) and 0 < d <= 1.3 * (radii[i] + radii[j]):
            w = occ[i] * occ[j] / (d * d)
            total += w * (en[i] - en[j]) ** 2
            weight += w
    return sqrt(total / weight) if weight > 0 else 0.0"},{"description":"Fraction of occupied adaptive-first-shell contacts joining the same element.","name":"homoelement_first_shell_fraction","source":"def feature(s):
