            w = occ[i] * occ[j]
            weight += w
            if sites[i].get('element') == sites[j].get('element'):
                same += w
    return same / weight if weight > 0 else 0.0"},{"description":"Directed short H-H, B-B, C-C, N-N and O-O contact count per occupied atom.","name":"light_homopolar_contact_density","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = []
    occ = []
    elements = []
    for site in sites:
        element = site.get('element')
