        x = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and isfinite(fraction) and fraction > 0 and x is not None and isfinite(x):
            total += fraction * x
            weight += fraction
    return total / (weight * v) if weight > 0 else 0.0"},{"description":"Logarithmic ratio of longest to shortest lattice-vector length.","name":"log_lattice_anisotropy","source":"def feature(s):
    s = s or {}
    lattice = s.get('lattice') or {}
    lengths = lattice.get('lengths_A')
    if lengths is None:
        lengths = [lattice.get('a_A'), lattice.get('b_A'), lattice.get('c_A')]
    values = [x for x in lengths if x is not None and isfinite(x) and x > 0]
    if len(values) != 3:
        return 0.0
    return log(max(values) / min(values))"},{"description":"Mean normalized vector imbalance of first-shell bond directions; zero for balanced shells.","name":"first_shell_directional_imbalance","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    if not all(isfinite(x) for row in matrix for x in row):
        return 0.0
    n = len(sites)
    nearest = [inf] * n
    occ = []
    for site in sites:
        o = site.get('occupancy')
        occ.append(1.0 if o is None else max(0.0, o))
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    vx = [0.0] * n
    vy = [0.0] * n
    vz = [0.0] * n
    weights = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and 0 < d <= 1.25 * nearest[i]:
            fi = sites[i].get('frac_coords')
            fj = sites[j].get('frac_coords')
            image = edge.get('image')
            if fi is None or fj is None or image is None or len(fi) != 3 or len(fj) != 3 or len(image) != 3:
                continue
            a = fj[0] + image[0] - fi[0]
            b = fj[1] + image[1] - fi[1]
            c = fj[2] + image[2] - fi[2]
            x = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
            y = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
            z = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
            norm = sqrt(x * x + y * y + z * z)
            if norm > 0 and isfinite(norm):
                vx[i] += occ[j] * x / norm
                vy[i] += occ[j] * y / norm
                vz[i] += occ[j] * z / norm
                weights[i] += occ[j]
    total = 0.0
    weight = 0.0
    for i in range(n):
        if weights[i] > 0:
            total += occ[i] * sqrt(vx[i] ** 2 + vy[i] ** 2 + vz[i] ** 2) / weights[i]
            weight += occ[i]
    return total / weight if weight > 0 else 0.0"},{"description":"Mean relative endpoint covalent-radius mismatch across short contacts.","name":"contact_radius_mismatch","source":"def feature(s):
    s = s or {}
