        o = site.get('occupancy')
        occ.append(1.0 if o is None else max(0.0, o))
    n = len(sites)
    total = 0.0
    weight = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and radii[i] > 0 and radii[j] > 0 and d is not None and isfinite(d) and 0 < d <= 1.3 * (radii[i] + radii[j]):
            w = occ[i] * occ[j]
            total += w * 2.0 * abs(radii[i] - radii[j]) / (radii[i] + radii[j])
            weight += w
    return total / weight if weight > 0 else 0.0"}],"queries":[{"include_any":["C","N","H"],"n":30},{"include_any":["Si","P","B","Sb"],"n":25},{"include_any":["U","Th","Np","Pa","Ac","Pu"],"n":20}],"rationale":"Add packing, local coordination, bond chemistry and atomic-energy descriptors beyond Magpie; sample light-element networks, metalloids and sparsely represented actinides."}

