    for i in range(n):
        amounts[elements[i]] = amounts.get(elements[i], 0.0) + occ[i]
    weight = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.25 * (a + b):
                w = occ[i] * occ[j]
                weight += w
                if elements[i] != elements[j]:
                    unlike += w
    if weight <= 0:
        return 0.0
    expected = 1.0 - sum((v / total) ** 2 for v in amounts.values())
    return unlike / weight - expected"},{"description":"RMS site-to-neighborhood electronegativity imbalance within covalent range.","name":"local_electronegativity_imbalance","source":"def feature(s):
