        t[1] += w * y * y / norm2
        t[2] += w * z * z / norm2
        t[3] += w * x * y / norm2
        t[4] += w * x * z / norm2
        t[5] += w * y * z / norm2
        t[6] += w
    total = 0.0
    weight = 0.0
    for i in range(n):
        t = tensors[i]
