        if ri is not None and rj is not None and ri > 0 and rj > 0 and d is not None and d > 0:
            q = d / (ri + rj)
            if nearest[i] is None or q < nearest[i]:
                nearest[i] = q
    total = 0.0
    weight = 0.0
    for a, q in zip(sites, nearest):
        w = a.get('occupancy', 1.0)
        if q is not None and w is not None and w > 0:
            total += w * q
            weight += w
    return float(total / weight) if weight > 0 else 0.0"},{"description":"Sitewise dispersion of the shortest covalent-radius-normalized bond.","name":"nearest_covalent_ratio_std","source":"def feature(s):
    s = s or {}
