        if q is not None and w is not None and w > 0:
            wsum += w
            first += w * q
            second += w * q * q
    return float(sqrt(max(0.0, second / wsum - (first / wsum) ** 2))) if wsum > 0 else 0.0"},{"description":"Mean smooth coordination using covalent-radius-scaled distance weights and occupancies.","name":"smooth_covalent_coordination","source":"def feature(s):
    s = s or {}
