            q = d / (1.2 * (ri + rj))
            if q < 2.0:
                total += occ[i] * occ[j] * exp(-(q ** 6))
    den = sum(occ)
    return float(total / den) if den > 0 else 0.0"},{"description":"Relative dispersion of smooth local covalent coordination.","name":"covalent_coordination_heterogeneity","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
