    total = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = radii[i], radii[j]
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and d is not None and d > 0:
            overlap = max(0.0, 1.0 - d / (ri + rj))
            total += occ[i] * occ[j] * overlap * overlap
    den = sum(occ)
    return float(0.5 * total / den) if den > 0 else 0.0"},{"description":"Mean radial coefficient of variation within each site's adaptive first shell.","name":"first_shell_radial_distortion","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    nearest = [None for a in sites]
    for b in s.get('neighbors') or []:
        i = b['i']
        d = b.get('distance_A')
        if d is not None and d > 0 and (nearest[i] is None or d < nearest[i]):
            nearest[i] = d
    wsum = [0.0 for a in sites]
    first = [0.0 for a in sites]
    second = [0.0 for a in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if nearest[i] is not None and d is not None and 0 < d <= 1.3 * nearest[i]:
            w = max(0.0, sites[j].get('occupancy', 1.0) or 0.0)
            wsum[i] += w
            first[i] += w * d
            second[i] += w * d * d
    total = 0.0
    den = 0.0
    for i, a in enumerate(sites):
        w = max(0.0, a.get('occupancy', 1.0) or 0.0)
        if wsum[i] > 0 and first[i] > 0:
            mean = first[i] / wsum[i]
            total += w * sqrt(max(0.0, second[i] / wsum[i] - mean * mean)) / mean
            den += w
    return float(total / den) if den > 0 else 0.0"},{"description":"Fraction of smooth covalent contacts joining different elements.","name":"heteronuclear_contact_fraction","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    els = [a.get('element') for a in sites]
    radii = [(props.get(el) or {}).get('covalent_radius_A') for el in els]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    total = 0.0
    den = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = radii[i], radii[j]
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and d is not None and d > 0:
            q = d / (1.2 * (ri + rj))
            if q < 2.0:
                w = occ[i] * occ[j] * exp(-(q ** 6))
                den += w
                if els[i] != els[j]:
                    total += w
    return float(total / den) if den > 0 else 0.0"},{"description":"Smooth-contact-weighted absolute electronegativity difference.","name":"bond_electronegativity_contrast","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    p = [props.get(a.get('element')) or {} for a in sites]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    total = 0.0
    den = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = p[i].get('covalent_radius_A'), p[j].get('covalent_radius_A')
        ei, ej = p[i].get('eneg'), p[j].get('eneg')
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and ei is not None and ej is not None and d is not None and d > 0:
            q = d / (1.2 * (ri + rj))
            if q < 2.0:
                w = occ[i] * occ[j] * exp(-(q ** 6))
                total += w * abs(ei - ej)
                den += w
    return float(total / den) if den > 0 else 0.0"},{"description":"Per-atom short-range ionic-contact proxy using squared electronegativity contrast over distance.","name":"ionic_contact_strength","source":"def feature(s):
    s = s or {}
