    return float(total / den) if den > 0 else 0.0"},{"description":"Smooth-contact-weighted mismatch in H3 valence-electron counts.","name":"bond_valence_electron_mismatch","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    p = [props.get(a.get('element')) or {} for a in sites]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    total = 0.0
    den = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = p[i].get('covalent_radius_A'), p[j].get('covalent_radius_A')
        vi, vj = p[i].get('valence_electrons'), p[j].get('valence_electrons')
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and vi is not None and vj is not None and d is not None and d > 0:
            q = d / (1.2 * (ri + rj))
            if q < 2.0:
                w = occ[i] * occ[j] * exp(-(q ** 6))
                total += w * abs(vi - vj)
                den += w
    return float(total / den) if den > 0 else 0.0"},{"description":"Dispersion of signed site-to-neighbor electronegativity offsets, measuring chemical environment differentiation.","name":"local_electronegativity_offset_std","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    p = [props.get(a.get('element')) or {} for a in sites]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    offsets = [0.0 for a in sites]
    weights = [0.0 for a in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        ri, rj = p[i].get('covalent_radius_A'), p[j].get('covalent_radius_A')
        ei, ej = p[i].get('eneg'), p[j].get('eneg')
        d = b.get('distance_A')
        if ri is not None and rj is not None and ri > 0 and rj > 0 and ei is not None and ej is not None and d is not None and d > 0:
            q = d / (1.2 * (ri + rj))
            if q < 2.0:
                w = occ[j] * exp(-(q ** 6))
                offsets[i] += w * (ej - ei)
                weights[i] += w
    den = 0.0
    first = 0.0
    second = 0.0
    for i in range(len(sites)):
        if weights[i] > 0:
            value = offsets[i] / weights[i]
            den += occ[i]
            first += occ[i] * value
            second += occ[i] * value * value
    return float(sqrt(max(0.0, second / den - (first / den) ** 2))) if den > 0 else 0.0"},{"description":"Neutral electronegativity-charge pair sum with a force-shifted six-angstrom inverse-distance kernel.","name":"electronegativity_charge_pair_sum","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    en = [(props.get(a.get('element')) or {}).get('eneg') for a in sites]
    occ = [max(0.0, a.get('occupancy', 1.0) or 0.0) for a in sites]
    den = sum(occ[i] for i in range(len(sites)) if en[i] is not None)
    if den <= 0:
        return 0.0
    mean = sum(occ[i] * en[i] for i in range(len(sites)) if en[i] is not None) / den
    charges = [mean - value if value is not None else 0.0 for value in en]
    total = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and 0 < d < 6.0 and en[i] is not None and en[j] is not None:
            kernel = 1.0 / d - 1.0 / 6.0 + (d - 6.0) / 36.0
            total += occ[i] * occ[j] * charges[i] * charges[j] * kernel
    return float(0.5 * total / den)"}],"queries":[{"include_any":["C","N"],"n":30},{"include_any":["F","Cl"],"n":25},{"include_any":["U","Eu","Ce","Pr","Nd","Sc","Au"],"n":20}],"rationale":"Add packing, local geometry, bond chemistry and atomic-energy descriptors beyond Magpie; sample C/N, halides and heavy-element chemistries highlighted by validation errors."}

