        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                near[i] = min(near[i], d / (ri + rj))
    weight = sum(occ[i] for i in range(n) if near[i] < 1e30)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * near[i] for i in range(n) if near[i] < 1e30) / weight
    return sqrt(max(sum(occ[i] * (near[i] - mean) ** 2 for i in range(n) if near[i] < 1e30) / weight, 0.0))"},{"description":"Mean occupancy-weighted coordination within 1.3 times each site's nearest occupied-neighbor distance.","name":"adaptive_first_shell_coordination","source":"def feature(s):
