    return sqrt(max(variance, 0.0)) / mean"},{"description":"Mean within-site relative bond-length variance for neighbors within 1.5 nearest-neighbor distances.","name":"local_bond_length_distortion","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
