                w = occ[i] * occ[j]
                total += w * ((ri - rj) / (ri + rj)) ** 2
                weight += w
    return total / weight if weight > 0 else 0.0"},{"description":"Composition covariance of electronegativity and covalent radius, normalized by mean radius.","name":"electronegativity_size_coupling","source":"def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    weight = 0.0
    se = 0.0
    sr = 0.0
