            weight += x
            se += x * en
            sr += x * r
            ser += x * en * r
    if weight <= 0 or sr <= 0:
        return 0.0
    return (ser - se * sr / weight) / sr"},{"description":"Mean squared positive excess of each site's shortest radius-normalized contact above unity.","name":"covalent_underbonding_load","source":"def feature(s):
