    return float(max(0.0, min(1.0, 1.0 - 3.0 * eigenvalues[0] / trace)))"},{"description":"Signed nominal electron demand: groups 15-17 accept; groups 1, 2 and 13 donate.","name":"nominal_main_group_electron_demand","source":"def feature(s):
