    values = [(sums[i] / weights[i]) ** 2 for i in range(len(sites)) if weights[i] > 0]
    return sqrt(sum(values) / len(values)) if values else 0.0"},{"description":"Per-atom short-range electronegativity-gap-squared over distance bond sum.","name":"short_range_ionic_strength","source":"def feature(s):
