        if 0 <= i < len(sites) and 0 <= j < len(sites) and d <= 1.25 * nearest[i]:
            element = sites[j].get('element')
            if element is None:
                continue
            o = sites[j].get('occupancy')
            w = max(0.0, o if o is not None else 1.0)
            counts[i][element] = counts[i].get(element, 0.0) + w
            totals[i] += w
    entropy = 0.0
    number = 0
    for i in range(len(sites)):
        if totals[i] > 0:
            for count in counts[i].values():
                if count > 0:
                    p = count / totals[i]
                    entropy -= p * log(p)
            number += 1
    return entropy / number if number else 0.0"},{"description":"Mean magnitude of the first-shell unit-bond-vector average; measures local asymmetry.","name":"local_bond_vector_imbalance","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    if any(row is None or len(row) != 3 for row in matrix):
        return 0.0
    edges = s.get('neighbors') or []
    nearest = [inf] * len(sites)
    vectors = [[0.0, 0.0, 0.0] for site in sites]
    counts = [0] * len(sites)
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A')
        if i is not None and 0 <= i < len(sites) and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    for edge in edges:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if not (0 <= i < len(sites) and 0 <= j < len(sites)):
            continue
        if d > 1.25 * nearest[i]:
            continue
        a = sites[i].get('frac_coords')
        b = sites[j].get('frac_coords')
        image = edge.get('image')
        if a is None or b is None or image is None:
            continue
        if len(a) != 3 or len(b) != 3 or len(image) != 3:
            continue
        f = [b[k] + image[k] - a[k] for k in range(3)]
        v = [sum(f[k] * matrix[k][t] for k in range(3)) for t in range(3)]
        norm = sqrt(sum(x * x for x in v))
        if norm > 0:
            for t in range(3):
                vectors[i][t] += v[t] / norm
            counts[i] += 1
    values = [sqrt(sum(x * x for x in vectors[i])) / counts[i] for i in range(len(sites)) if counts[i] > 0]
    return sum(values) / len(values) if values else 0.0"},{"description":"Rotationally invariant anisotropy of local first-shell bond orientation tensors.","name":"local_bond_orientation_anisotropy","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    if any(row is None or len(row) != 3 for row in matrix):
        return 0.0
    edges = s.get('neighbors') or []
    nearest = [inf] * len(sites)
    moments = [[0.0] * 6 for site in sites]
    counts = [0] * len(sites)
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A')
        if i is not None and 0 <= i < len(sites) and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    for edge in edges:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if not (0 <= i < len(sites) and 0 <= j < len(sites)):
            continue
        if d > 1.25 * nearest[i]:
            continue
        a = sites[i].get('frac_coords')
        b = sites[j].get('frac_coords')
        image = edge.get('image')
        if a is None or b is None or image is None:
            continue
        if len(a) != 3 or len(b) != 3 or len(image) != 3:
            continue
        f = [b[k] + image[k] - a[k] for k in range(3)]
        v = [sum(f[k] * matrix[k][t] for k in range(3)) for t in range(3)]
        norm = sqrt(sum(x * x for x in v))
        if norm <= 0:
            continue
        x = v[0] / norm
        y = v[1] / norm
        z = v[2] / norm
        terms = [x*x, y*y, z*z, x*y, x*z, y*z]
        for t in range(6):
            moments[i][t] += terms[t]
        counts[i] += 1
    total = 0.0
    number = 0
    for i in range(len(sites)):
        if counts[i] > 0:
            q = [x / counts[i] for x in moments[i]]
            tr = q[0]**2 + q[1]**2 + q[2]**2 + 2.0 * (q[3]**2 + q[4]**2 + q[5]**2)
            total += max(0.0, min(1.0, (3.0 * tr - 1.0) / 2.0))
            number += 1
    return total / number if number else 0.0"},{"description":"Mean tetrahedral angular order of the four nearest periodic neighbors.","name":"nearest_four_tetrahedral_order","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    if any(row is None or len(row) != 3 for row in matrix):
        return 0.0
    bonds = [[] for site in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if not (0 <= i < len(sites) and 0 <= j < len(sites)):
            continue
        if len(bonds[i]) == 4 and d > bonds[i][3][0]:
            continue
        a = sites[i].get('frac_coords')
        b = sites[j].get('frac_coords')
        image = edge.get('image')
        if a is None or b is None or image is None:
            continue
        if len(a) != 3 or len(b) != 3 or len(image) != 3:
            continue
        f = [b[k] + image[k] - a[k] for k in range(3)]
        v = [sum(f[k] * matrix[k][t] for k in range(3)) for t in range(3)]
        norm = sqrt(sum(x * x for x in v))
        if norm > 0:
            bond = (d, v[0] / norm, v[1] / norm, v[2] / norm)
            bonds[i] = sorted(bonds[i] + [bond])[:4]
    total = 0.0
    number = 0
    for local in bonds:
        if len(local) == 4:
            penalty = 0.0
            for a in range(4):
                for b in range(a + 1, 4):
                    dot = sum(local[a][k] * local[b][k] for k in range(1, 4))
                    penalty += (max(-1.0, min(1.0, dot)) + 1.0 / 3.0) ** 2
            total += 1.0 - 0.375 * penalty
            number += 1
    return total / number if number else 0.0"},{"description":"Inverse-distance-weighted minimum atomic electron-transfer cost on heterochemical shell contacts.","name":"shell_atomic_electron_transfer_cost","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    ip = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    ea = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') for x in sites]
    edges = s.get('neighbors') or []
    nearest = [inf] * len(sites)
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A')
        if i is not None and 0 <= i < len(sites) and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    weight = 0.0
    for edge in edges:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if not (0 <= i < len(sites) and 0 <= j < len(sites)):
            continue
        if d > 1.25 * nearest[i] or sites[i].get('element') == sites[j].get('element'):
            continue
        cost = None
        if ip[i] is not None and ea[j] is not None:
            cost = ip[i] - ea[j]
        if ip[j] is not None and ea[i] is not None:
            reverse = ip[j] - ea[i]
            cost = reverse if cost is None else min(cost, reverse)
        if cost is not None:
            total += cost / d
            weight += 1.0 / d
    return total / weight if weight > 0 else 0.0"}],"queries":[{"include_any":["C","N"],"n":25},{"include_any":["F","Cl","P","Si"],"n":25,"n_elements":[3,7]},{"include_any":["U","Th","Np","Pu","Ac","Pa","Eu","Nd"],"n":25}],"rationale":"Add packing, contact strain, local chemistry and angular order beyond Magpie; sample C/N, halide/pnictogen and heavy-element chemistries highlighted by validation errors."}

