@5 n="electronegativity_size_coupling" d="Composition covariance of electronegativity and covalent radius, normalized by mean radius." B=572
def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    weight = 0.0
    se = 0.0
    sr = 0.0
    ser = 0.0
    for e, x in (s.get('composition') or {}).items():
        a = p.get(e) or {}
        en = a.get('eneg')
        r = a.get('covalent_radius_A')
        if x is not None and x > 0 and en is not None and r is not None and r > 0:
            weight += x
            se += x * en
            sr += x * r
            ser += x * en * r
    if weight <= 0 or sr <= 0:
        return 0.0
    return (ser - se * sr / weight) / sr

