    trace = sum(tensor[k][k] for k in range(3))
    if trace <= 1e-12:
        return 0.0
    eigen = np.linalg.eigvalsh(np.array(tensor))
    return float(max(0.0, min(1.0, 3.0 * eigen[0] / trace)))"},{"description":"Contact-weighted minimum directional atomic ionization-minus-affinity cost across unlike-element pairs.","name":"contact_atomic_transfer_cost","source":"def feature(s):
