    total = sum(occ)
    return sum(occ[i] * coordination[i] for i in range(n)) / total if total > 0 else 0.0"},{"description":"Site-to-site standard deviation of occupancy-weighted adaptive-shell coordination.","name":"adaptive_shell_coordination_std","source":"def feature(s):
