            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Fraction of occupied atoms in isolated short-bond dimers whose atoms both belong to groups 14–17.","name":"p_block_isolated_dimer_fraction","source":"def feature(s):
