            if a is not None and b is not None and 14 <= a <= 17 and 14 <= b <= 17:
                value += occ[i]
    total = sum(occ)
    return value / total if total > 0 else 0.0"},{"description":"Mean within-site coefficient of variation of distances in the adaptive 1.25-nearest-distance shell.","name":"local_shell_radial_distortion","source":"def feature(s):
    if not s:
