            nearest[i] = min(nearest[i], d)
    weights = [0.0] * n
    first = [0.0] * n
    second = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and d <= 1.25 * nearest[i]:
            weights[i] += occ[j]
            first[i] += occ[j] * d
            second[i] += occ[j] * d * d
    value = 0.0
    total = 0.0
    for i in range(n):
        if weights[i] > 0 and first[i] > 0:
            mean = first[i] / weights[i]
            variance = max(0.0, second[i] / weights[i] - mean * mean)
            value += occ[i] * sqrt(variance) / mean
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Mean rotationally invariant anisotropy of adaptive-shell bond-direction second moments; zero is isotropic, one is collinear.","name":"local_shell_directional_anisotropy","source":"def feature(s):
    if not s:
        return 0.0
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    nearest = [inf] * n
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    moments = [[0.0] * 6 for i in range(n)]
    weights = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and d > 0 and d <= 1.25 * nearest[i]:
            a = sites[i].get('frac_coords')
            b = sites[j].get('frac_coords')
            image = edge.get('image')
            if a is None or b is None or image is None or len(a) != 3 or len(b) != 3 or len(image) != 3:
                continue
            f = [b[k] + image[k] - a[k] for k in range(3)]
            v = [sum(f[k] * matrix[k][t] for k in range(3)) for t in range(3)]
            norm = sqrt(sum(x * x for x in v))
            if norm <= 0:
                continue
            x = v[0] / norm
            y = v[1] / norm
            z = v[2] / norm
            terms = [x*x, y*y, z*z, x*y, x*z, y*z]
            for k in range(6):
                moments[i][k] += occ[j] * terms[k]
            weights[i] += occ[j]
    value = 0.0
    total = 0.0
    for i in range(n):
        if weights[i] > 0:
            m = [x / weights[i] for x in moments[i]]
            trace_square = sum(m[k] ** 2 for k in range(3)) + 2.0 * sum(m[k] ** 2 for k in range(3, 6))
            value += occ[i] * sqrt(max(0.0, min(1.0, 1.5 * trace_square - 0.5)))
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Maximum translation rank of a connected short-covalent-bond network: molecular zero, chain one, layer two, framework three.","name":"covalent_network_periodic_rank","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    adjacency = [[] for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        image = edge.get('image')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and d > 0 and image is not None and len(image) == 3:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.2 * (a + b):
                adjacency[i] += [(j, tuple(image))]
    shifts = [None] * n
    best = 0
    for root in range(n):
        if shifts[root] is not None or occ[root] <= 0:
            continue
        shifts[root] = (0, 0, 0)
        queue = [root]
        cycles = []
        for q in range(n):
            if q >= len(queue):
                break
            i = queue[q]
            for j, image in adjacency[i]:
                candidate = tuple(shifts[i][k] + image[k] for k in range(3))
                if shifts[j] is None:
                    shifts[j] = candidate
                    queue += [j]
                else:
                    residual = tuple(candidate[k] - shifts[j][k] for k in range(3))
                    if any(x != 0 for x in residual):
                        cycles += [residual]
        if len(cycles) > 0:
            rank = int(np.linalg.matrix_rank(np.asarray(cycles, dtype=float), tol=1e-7))
            best = max(best, rank)
            if best == 3:
                return 3.0
    return float(best)"},{"description":"Mean squared difference between a site's electronegativity and its adaptive-shell neighbor average, measuring local chemical polarity.","name":"local_environment_chemical_polarity","source":"def feature(s):
    if not s:
