        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and chi[j] is not None and d is not None and d > 0 and d <= 1.25 * nearest[i]:
            w = occ[j] / max(d * d, 0.01)
            weights[i] += w
            neighbor_chi[i] += w * chi[j]
    value = 0.0
    total = 0.0
    for i in range(n):
        if chi[i] is not None and weights[i] > 0:
            contrast = neighbor_chi[i] / weights[i] - chi[i]
            value += occ[i] * contrast * contrast
            total += occ[i]
    return value / total if total > 0 else 0.0"}],"queries":[{"include_any":["C","N"],"n":37},{"include_any":["Au","U","Th","W","Zr"],"n":23},{"include_any":["F","Cl","Br"],"n":15}],"rationale":"Add covalent strain, local polarity, coordination, molecularity and periodic connectivity. Prioritize scarce C/N examples and heavy-element/halide coverage."}

