    nearest = [inf] * n
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    count = [0.0] * n
    first = [0.0] * n
    second = [0.0] * n
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 1e-8 < d <= 1.25 * nearest[i]:
            count[i] += occ[j]
            first[i] += occ[j] * d
            second[i] += occ[j] * d * d
    total = 0.0
    weight = 0.0
    for i in range(n):
