            mean = first[i] / count[i]
            variance = max(second[i] / count[i] - mean * mean, 0.0)
            total += occ[i] * sqrt(variance) / mean
            weight += occ[i]
    return total / weight if weight > 0 else 0.0"},{"description":"First-shell sum of squared electronegativity differences divided by bond length, per occupied atom.","name":"ionic_contact_strength","source":"def feature(s):
