        moments[i, 0] += q * x * x
        moments[i, 1] += q * y * y
        moments[i, 2] += q * z * z
        moments[i, 3] += q * x * y
        moments[i, 4] += q * x * z
        moments[i, 5] += q * y * z
        counts[i] += occ[j]
    total = 0.0
    weight = 0.0
    for i in range(n):
        if counts[i] > 0 and occ[i] > 0:
            square = moments[i, 0] ** 2 + moments[i, 1] ** 2 + moments[i, 2] ** 2
            square += 2.0 * (moments[i, 3] ** 2 + moments[i, 4] ** 2 + moments[i, 5] ** 2)
            value = min(max(0.5 * (3.0 * square / counts[i] ** 2 - 1.0), 0.0), 1.0)
            total += occ[i] * value
            weight += occ[i]
    return total / weight if weight > 0 else 0.0"},{"description":"Mean magnitude of the occupancy-weighted first-shell unit-vector resultant, normalized by coordination.","name":"first_shell_directional_imbalance","source":"def feature(s):
