    total = 0.0
    weight = 0.0
    for i in range(n):
        if counts[i] > 0 and occ[i] > 0:
            length = sqrt(vectors[i, 0] ** 2 + vectors[i, 1] ** 2 + vectors[i, 2] ** 2)
            total += occ[i] * min(length / counts[i], 1.0)
            weight += occ[i]
    return total / weight if weight > 0 else 0.0"},{"description":"Occupied-site mean periodic dimensionality of connected components in the symmetrized adaptive first-shell graph.","name":"first_shell_network_periodicity","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    parent = list(range(n))
    size = [1] * n
    shift = np.zeros((n, 3))
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0):
            continue
        if d > 1.25 * nearest[i] and d > 1.25 * nearest[j]:
            continue
        ri = i
        rj = j
        ti = np.zeros(3)
        tj = np.zeros(3)
        for k in range(n):
            if parent[ri] == ri:
                break
            ti = ti + shift[ri]
            ri = parent[ri]
        for k in range(n):
            if parent[rj] == rj:
                break
            tj = tj + shift[rj]
            rj = parent[rj]
        if ri == rj:
            continue
        image = np.asarray(b.get('image') or (0, 0, 0))
        delta = ti + image - tj
        if size[ri] >= size[rj]:
            parent[rj] = ri
            shift[rj] = delta
            size[ri] += size[rj]
        else:
            parent[ri] = rj
            shift[ri] = -delta
            size[rj] += size[ri]
    roots = [0] * n
    offsets = np.zeros((n, 3))
    for i in range(n):
        r = i
        for k in range(n):
            if parent[r] == r:
                break
            offsets[i] = offsets[i] + shift[r]
            r = parent[r]
        roots[i] = r
    cycles = np.zeros((n, 3, 3))
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0):
            continue
        if d > 1.25 * nearest[i] and d > 1.25 * nearest[j]:
            continue
        image = np.asarray(b.get('image') or (0, 0, 0))
        c = offsets[i] + image - offsets[j]
        r = roots[i]
        cycles[r] = cycles[r] + c.reshape(3, 1) * c.reshape(1, 3)
    ranks = [0.0] * n
    for i in range(n):
        if parent[i] == i:
            ranks[i] = float(np.linalg.matrix_rank(cycles[i]))
    return sum(occ[i] * ranks[roots[i]] for i in range(n)) / weight"}],"queries":[{"exclude":["O","F","Cl","Br","I","S","Se","Te"],"include_any":["Ag","Ga","Rb","Cs"],"n":25,"n_elements":[2,4]},{"include_all":["N"],"include_any":["O","F","Cl"],"n":25,"n_elements":[3,5]},{"include_any":["Zr","Nb","Tl","Te","Nd","Ir","Re","Th","Ta"],"n":25}],"rationale":"Combine charge balance with adaptive coordination, local bonding, angular geometry and network periodicity; query molecular-anion, metal-rich and sparsely sampled chemistries."}

