    scale = 0.0
    for e, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        a = p.get(e) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = None
        if g == 1 or g == 2:
            q = float(g)
