    return sum(occ[i] * (signed[i] / weights[i]) ** 2 for i in range(n) if weights[i] > 0) / total if total > 0 else 0.0"},{"description":"Mean local distance coefficient of variation within 1.5 times the nearest-neighbor distance.","name":"local_radial_shell_distortion","source":"def feature(s):
    if not s:
