    weights = [0.0] * n
    first = [0.0] * n
    second = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and nearest[i] is not None:
            if d <= 1.5 * nearest[i]:
                weights[i] += occ[j]
                first[i] += occ[j] * d
                second[i] += occ[j] * d * d
    value = 0.0
    total = 0.0
    for i in range(n):
        if weights[i] > 0 and first[i] > 0:
            mean = first[i] / weights[i]
            variance = max(0.0, second[i] / weights[i] - mean * mean)
            value += occ[i] * sqrt(variance) / mean
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Rotationally invariant anisotropy of first-shell bond-direction tensors: zero for isotropic shells and one for collinear shells.","name":"first_shell_directional_anisotropy","source":"def feature(s):
    if not s:
