    total = sum(occ[i] for i in range(n) if r[i] is not None and r[i] > 0)
    return value / total if total > 0 else 0.0"},{"description":"Nominal occupied covalent-sphere volume divided by cell volume; overlaps are intentionally retained.","name":"covalent_sphere_packing_fraction","source":"def feature(s):
    if not s:
