    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * occupied if v is not None and v > 0 else 0.0
    return sphere_volume / volume if volume > 0 else 0.0"},{"description":"Occupied-atom-weighted periodic dimensionality of covalent-contact components: molecular zero, chains one, layers two, frameworks three.","name":"covalent_network_periodic_dimensionality","source":"def feature(s):
    if not s:
