                coordination[i] += occ[j]
    value = 0.0
    total = 0.0
    for i in range(n):
        g = groups[i]
        if g is not None and 13 <= g <= 17 and r[i] is not None and r[i] > 0:
            degree = 3.0 if g == 13 else 18.0 - g
            value += occ[i] * (coordination[i] - degree) ** 2
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Rotation-invariant anisotropy of local first-shell bond-direction tensors; zero is isotropic and one is linear.","name":"local_bond_direction_anisotropy","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    coords = [x.get('frac_coords') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    tensors = [[0.0] * 6 for x in sites]
    weights = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if not (0 <= i < n and 0 <= j < n and d is not None and d > 0 and d <= 1.2 * nearest[i] and occ[j] > 0):
            continue
        if coords[i] is None or coords[j] is None or len(coords[i]) != 3 or len(coords[j]) != 3:
            continue
        image = edge.get('image')
        if image is None or len(image) != 3:
            continue
        f = [coords[j][k] + image[k] - coords[i][k] for k in range(3)]
        x = f[0] * matrix[0][0] + f[1] * matrix[1][0] + f[2] * matrix[2][0]
        y = f[0] * matrix[0][1] + f[1] * matrix[1][1] + f[2] * matrix[2][1]
        z = f[0] * matrix[0][2] + f[1] * matrix[1][2] + f[2] * matrix[2][2]
        norm2 = x * x + y * y + z * z
        if norm2 <= 0:
            continue
        w = occ[j] / norm2
        tensors[i][0] += w * x * x
        tensors[i][1] += w * y * y
        tensors[i][2] += w * z * z
        tensors[i][3] += w * x * y
        tensors[i][4] += w * x * z
        tensors[i][5] += w * y * z
        weights[i] += occ[j]
    value = 0.0
    total = 0.0
    for i in range(n):
        if weights[i] > 0:
            t = tensors[i]
            trace2 = (t[0] ** 2 + t[1] ** 2 + t[2] ** 2 + 2.0 * (t[3] ** 2 + t[4] ** 2 + t[5] ** 2)) / weights[i] ** 2
            value += occ[i] * min(1.0, max(0.0, (3.0 * trace2 - 1.0) / 2.0))
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Short-contact squared atomic chemical-potential differences divided by summed hardness, accumulated per occupied atom.","name":"short_contact_mu_hardness_load","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
