    weight = sum(occ[i] for i in range(n) if r[i] is not None and r[i] > 0)
    return sum(occ[i] * exp(-cn[i]) for i in range(n) if r[i] is not None and r[i] > 0) / weight if weight > 0 else 0.0"},{"description":"Squared electronegativity contrast weighted by short covalent contacts, per occupied atom.","name":"heteropolar_contact_load","source":"def feature(s):
