    nearest = [None for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                t = d / (r[i] + r[j])
                if nearest[i] is None or t < nearest[i]:
                    nearest[i] = t
    weight = sum(occ[i] for i in range(n) if nearest[i] is not None)
    return sum(occ[i] * nearest[i] for i in range(n) if nearest[i] is not None) / weight if weight > 0 else 0.0

