                w = occ[i] * occ[j]
                total += w
                if elements[i] != elements[j]:
                    hetero += w
    return hetero / total if total > 0 else 0.0"},{"description":"Occupied covalent-sphere volume divided by cell volume; overlapping spheres are not clipped.","name":"covalent_sphere_packing_fraction","source":"def feature(s):
