    return sqrt(max(0.0, sum(occ[i] * (nearest[i] - mean) ** 2 for i in range(n) if isfinite(nearest[i])) / total))"},{"description":"Mean smooth covalent coordination; contacts beyond the radius sum decay with reduced-distance width 0.2.","name":"mean_smooth_covalent_coordination","source":"def feature(s):
