        if g is not None and 14 <= g <= 17 and r is not None and r > 0:
            value += occ[i] * max(0.0, 18.0 - g - coordination[i])
    total = sum(occ)
    return value / total if total > 0 else 0.0"},{"description":"Mean local bond-length coefficient of variation within 1.25 times each site's nearest-neighbor distance.","name":"nearest_shell_length_disorder","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    weights = [0.0] * n
    first = [0.0] * n
    second = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and isfinite(nearest[i]) and d <= 1.25 * nearest[i]:
            x = d / nearest[i]
            weights[i] += occ[j]
            first[i] += occ[j] * x
            second[i] += occ[j] * x * x
    value = 0.0
    total = 0.0
    for i in range(n):
        if weights[i] > 0 and first[i] > 0:
            mean = first[i] / weights[i]
            variance = max(0.0, second[i] / weights[i] - mean * mean)
            value += occ[i] * sqrt(variance) / mean
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Rotation-invariant anisotropy of local nearest-shell direction tensors: zero isotropic, one collinear.","name":"nearest_shell_direction_anisotropy","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    coords = [x.get('frac_coords') for x in sites]
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    tensors = [[[0.0 for b in range(3)] for a in range(3)] for i in range(n)]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0 and isfinite(nearest[i]) and d <= 1.25 * nearest[i]:
            fi = coords[i]
            fj = coords[j]
            image = edge.get('image')
            if fi is not None and fj is not None and image is not None and len(fi) == 3 and len(fj) == 3 and len(image) == 3:
                delta = [fj[k] + image[k] - fi[k] for k in range(3)]
                vector = [sum(delta[k] * matrix[k][a] for k in range(3)) for a in range(3)]
                norm2 = sum(x * x for x in vector)
                if norm2 > 0:
                    for a in range(3):
                        for b in range(3):
                            tensors[i][a][b] += occ[j] * vector[a] * vector[b] / norm2
    value = 0.0
    total = 0.0
    for i in range(n):
        trace = sum(tensors[i][a][a] for a in range(3))
        if trace > 0:
            square = sum(tensors[i][a][b] ** 2 for a in range(3) for b in range(3))
            anisotropy = max(0.0, min(1.0, (3.0 * square / (trace * trace) - 1.0) / 2.0))
            value += occ[i] * anisotropy
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Short-contact chemical assortativity relative to random mixing at the occupied-site composition.","name":"covalent_chemical_assortativity","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [x.get('element') for x in sites]
    radii = [(props.get(e) or {}).get('covalent_radius_A') for e in elements]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    counts = {}
    occupied = 0.0
    for i in range(n):
        if radii[i] is not None and radii[i] > 0:
            counts[elements[i]] = counts.get(elements[i], 0.0) + occ[i]
            occupied += occ[i]
    if occupied <= 0:
        return 0.0
    expected = 1.0 - sum((v / occupied) ** 2 for v in counts.values())
    if expected <= 1e-12:
        return 0.0
    unlike = 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.3 * (a + b):
                w = occ[i] * occ[j]
                total += w
                if elements[i] != elements[j]:
                    unlike += w
    return 1.0 - unlike / (total * expected) if total > 0 else 0.0"},{"description":"Mean relative gap between the first and second periodic neighbor distances, including distinct images.","name":"first_second_neighbor_gap","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    first = [inf] * n
    second = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            if d < first[i]:
                second[i] = first[i]
                first[i] = d
            elif d < second[i]:
                second[i] = d
    value = 0.0
    total = 0.0
    for i in range(n):
        if first[i] > 0 and isfinite(second[i]):
            value += occ[i] * (second[i] / first[i] - 1.0)
            total += occ[i]
    return value / total if total > 0 else 0.0"},{"description":"Mean squared difference between site electronegativity and its weighted short-contact environment mean.","name":"coherent_environment_electronegativity_contrast","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
