            total += occ[i]
    return value / total if total > 0 else 0.0"}],"queries":[{"include_any":["Au","Nd","U"],"n":25},{"include_any":["H","B","Si","P"],"n":25},{"include_any":["F","Cl","Br"],"n":25,"n_elements":[2,3]}],"rationale":"Add packing, coordination deficits, shell gaps and directional chemistry to resolve strained or molecular environments. Sample scarce heavy elements, covalent chemistries and simple halides."}

