            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and en[i] is not None and en[j] is not None:
                w = max(1.5 - d / (r[i] + r[j]), 0.0) ** 2
                total += occ[i] * occ[j] * w * (en[i] - en[j]) ** 2
    return total / (2.0 * weight)"},{"description":"Fraction of short contacts from electronegative sites to neighbors at least 0.5 less electronegative.","name":"anion_heteropolar_contact_fraction","source":"def feature(s):
