@5 n="atomic_volume" d="Volume per atom, with occupancy-based cell-volume fallback." B=436
def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is not None and v > 0:
        return float(v)
    occupied = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        occupied += max(0.0, o if o is not None else 1.0)
    volume = (s.get('lattice') or {}).get('volume_A3')
    return volume / occupied if volume is not None and volume > 0 and occupied > 0 else 0.0
@end
@6 n="mean_valence_f_subshell_occupancy" d="Composition-weighted f occupancy in the supplied valence-subshell convention." B=631
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    value = 0.0
    total = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        shell = (props.get(element) or {}).get('pymatgen_valence_subshell')
        if fraction is not None and fraction > 0 and shell is not None and len(shell) == 2:
            l = shell[0]
            count = shell[1]
            if l is not None and count is not None:
                total += fraction
                if l == 3:
                    value += fraction * max(0.0, count)
    return value / total if total > 0 else 0.0
@end
@7 n="short_bond_electronegativity_contrast" d="Mean squared electronegativity difference across short contacts, weighted by occupancy and inverse squared distance." B=1045
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    chi = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    value = 0.0
    weight = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and chi[i] is not None and chi[j] is not None:
                if d <= 1.3 * (a + b):
                    w = occ[i] * occ[j] / max(d * d, 0.01)
                    value += w * (chi[i] - chi[j]) ** 2
                    weight += w
    return value / weight if weight > 0 else 0.0
@end
