                    first += w * ratio
                    second += w * ratio * ratio
    return sqrt(max(0.0, second / total - (first / total) ** 2)) if total > 0 else 0.0"},{"description":"Mean squared deviation of smooth geometric coordination from simple group 13–17 octet neighbor counts; not a bond-order assignment.","name":"p_block_coordination_mismatch","source":"def feature(s):
    if not s:
