            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.3 * (a + b):
                if chi[i] is not None and chi[j] is not None:
                    denominator = 2.0 * (hardness[i] + hardness[j])
                    if denominator > 0:
                        value += occ[i] * occ[j] * (chi[i] - chi[j]) ** 2 / denominator
    total = sum(occ)
    return 0.5 * value / total if total > 0 else 0.0"},{"description":"Mean squared difference between each site's electronegativity and its short-neighbor average.","name":"local_electronegativity_imbalance","source":"def feature(s):
