@14 n="electronegative_homoelement_compression" d="Squared compression of same-element covalent contacts on electronegative atoms, per occupied atom." B=929
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    elements = [a.get('element') for a in sites]
    r = [(p.get(e) or {}).get('covalent_radius_A') for e in elements]
    en = [(p.get(e) or {}).get('eneg') for e in elements]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and elements[i] == elements[j]:
            if r[i] is not None and r[i] > 0 and en[i] is not None and en[i] >= 2.0:
                compression = max(1.0 - d / (2.0 * r[i]), 0.0)
                total += occ[i] * occ[j] * compression * compression
    return total / (2.0 * weight)
