                second[i] = d
    total = 0.0
    weight = 0.0
    for i in range(n):
        if first[i] <= 6.0:
            outer = min(second[i], 6.0)
            gap = min(max(outer / first[i] - 1.0, 0.0), 3.0)
            total += occ[i] * gap
