    return total / weight if weight > 0 else 0.0"}],"queries":[{"include_all":["N","O"],"n":25},{"exclude":["O"],"include_all":["N"],"n":25},{"include_all":["Br"],"n":25}],"rationale":"Add local bond-capacity imbalance, directional asymmetry, packing and isolated-bond signals; sample nitrogen and bromide chemistry to address prominent residual motifs."}

