    for b in neighbors:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if not (0 <= i < n and 0 <= j < n and d > 0 and isfinite(near[i]) and d <= 1.5 * near[i]):
            continue
        fi = sites[i].get('frac_coords')
        fj = sites[j].get('frac_coords')
        image = b.get('image')
        if fi is None or fj is None or image is None:
            continue
        u = fj[0] + image[0] - fi[0]
        v = fj[1] + image[1] - fi[1]
        z = fj[2] + image[2] - fi[2]
        x = u * matrix[0][0] + v * matrix[1][0] + z * matrix[2][0]
        y = u * matrix[0][1] + v * matrix[1][1] + z * matrix[2][1]
        zz = u * matrix[0][2] + v * matrix[1][2] + z * matrix[2][2]
        norm2 = x * x + y * y + zz * zz
