            w = o[i] * o[j] * exp(1.0 - (d / near[i]) ** 6)
            total += w * min(costs)
            weight += w
    return total / weight if weight > 0 else 0.0"},{"description":"RMS difference between site electronegativity and its soft first-shell mean electronegativity.","name":"local_electronegativity_field_rms","source":"def feature(s):
