            total += o[i] * sqrt(var) / mean
            weight += o[i]
    return total / weight if weight > 0 else 0.0"},{"description":"Mean rotationally invariant anisotropy of local first-shell bond-direction tensors.","name":"local_bond_direction_anisotropy","source":"def feature(s):
    t = s or {}
