        w = o[j] * exp(1.0 - (d / near[i]) ** 6) / norm2
        a = tensors[i]
        a[0] += w * x * x
        a[1] += w * y * y
        a[2] += w * zz * zz
        a[3] += w * x * y
        a[4] += w * x * zz
        a[5] += w * y * zz
    total = 0.0
    weight = 0.0
    for i in range(n):
        a = tensors[i]
