            value = max(0.0, min(1.0, 0.5 * (3.0 * square / (trace * trace) - 1.0)))
            total += o[i] * value
            weight += o[i]
    return total / weight if weight > 0 else 0.0"},{"description":"Ideal compositional mixing entropy divided by Boltzmann's constant.","name":"composition_mixing_entropy","source":"def feature(s):
