            near[i] = min(near[i], d)
    weights = [0.0] * n
    first = [0.0] * n
    second = [0.0] * n
    for b in edges:
        i, j = b.get('i', -1), b.get('j', -1)
        d = b.get('distance_A')
        if not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if isfinite(near[i]) and near[i] > 0 and d <= 1.8 * near[i]:
            u = d / near[i]
            w = occ[j] * exp(1.0 - u ** 6)
            weights[i] += w
            first[i] += w * u
            second[i] += w * u * u
    total = 0.0
    z = 0.0
    for i in range(n):
        if weights[i] > 0:
            total += occ[i] * max(0.0, second[i] / weights[i] - (first[i] / weights[i]) ** 2)
            z += occ[i]
    return sqrt(total / z) if z > 0 else 0.0"},{"description":"Per-atom sum of squared positive covalent-radius contact overlaps.","name":"covalent_overlap_burden","source":"def feature(s):
