        norm += w
        if elements[i] != elements[j]:
            unlike += w
    return unlike / norm - random_unlike if norm > 0 else 0.0"},{"description":"Weighted electronegativity correlation between the endpoints of periodic contacts.","name":"electronegativity_contact_assortativity","source":"def feature(s):
