        if not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        a, c, x, y = radii[i], radii[j], chi[i], chi[j]
        if a is None or c is None or x is None or y is None:
            continue
        if not all(isfinite(v) for v in [a, c, x, y]) or a <= 0 or c <= 0 or x <= 0 or y <= 0:
            continue
        u = d / (a + c)
        w = occ[i] * occ[j] * exp(2.0 - 2.0 * u * u)
        norm += w
        first += 0.5 * w * (x + y)
        second += 0.5 * w * (x*x + y*y)
        cross += w * x * y
    if norm <= 0:
        return 0.0
    mean = first / norm
    var = second / norm - mean * mean
    if var <= 1e-12:
        return 0.0
    return max(-1.0, min(1.0, (cross / norm - mean * mean) / var))"},{"description":"Per-atom density of homonuclear electronegative p-block contacts, including molecular motifs.","name":"electronegative_homonuclear_contacts","source":"def feature(s):
