        a, c, x, y = radii[i], radii[j], ion[i], ion[j]
        if any(v is None for v in [a, c, x, y]):
            continue
        if not all(isfinite(v) for v in [a, c, x, y]) or min(a, c, x, y) <= 0:
            continue
        term = 1.5 * x * y / (x + y) * (a * c) ** 3 / (d ** 6 + (a + c) ** 6)
        total += occ[i] * occ[j] * term
    return total / (2.0 * z)"},{"description":"Contact density weighted by products of neutral-atom open d/f subshell occupancy proxies.","name":"open_df_shell_contact_density","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    props = [ep.get(x.get('element')) or {} for x in sites]
    radii = [p.get('covalent_radius_A') for p in props]
    open_shell = []
    for p in props:
        q = p.get('pymatgen_valence_subshell')
        h = 0.0
        if q is not None and len(q) == 2:
            l, v = q[0], q[1]
            if l is not None and v is not None and isfinite(l) and isfinite(v) and l >= 2:
                capacity = 2.0 * (2.0 * l + 1.0)
                h = max(0.0, min(v, capacity - v))
        open_shell.append(h)
    occ = [1.0 if x.get('occupancy') is None else max(0.0, x.get('occupancy')) for x in sites]
    n = len(sites)
    z = sum(occ)
    if z <= 0:
        return 0.0
