            z += occ[i]
    return sqrt(total / z) if z > 0 else 0.0"}],"notes":"Periodic contacts are occupancy-weighted; covalent-radius and atomic-energy descriptors are bonding proxies, not assigned oxidation states or formation energies.","queries":[{"include_any":["Re","Np","Ir","Au"],"n":25},{"include_all":["O"],"include_any":["P","N","B","Al","Mn","V"],"n":30},{"exclude":["O"],"include_any":["La","Pr","Tm","Er","Ho","Y"],"n":20}],"rationale":"Add geometry-aware bonding and atomic-energy descriptors beyond Magpie; enrich rare heavy-element, oxygen-rich, and nonoxide rare-earth coverage."}

